import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
const root=new URL('../../..',import.meta.url).pathname.replace(/\/$/,'');
const deps=process.env.FORKLAUNCH_TEST_BETTER_AUTH_DEPENDENCIES;
const {betterAuthReference}=await import(pathToFileURL(root+'/cli/tests/fixtures/rust_better_auth_reference.mjs'));
const {betterAuth}=await import(pathToFileURL(deps+'/node_modules/better-auth/dist/index.mjs'));
const {organization}=await import(pathToFileURL(deps+'/node_modules/better-auth/dist/plugins/organization/index.mjs'));
const ref=await betterAuthReference(root);
const call=async(auth,path,body,cookie='')=>{const r=await auth.handler(new Request('http://localhost:3000/api/auth'+path,{method:body?'POST':'GET',headers:{origin:'http://localhost:3000','content-type':'application/json',cookie},...(body?{body:JSON.stringify(body)}:{})}));const text=await r.text();return {status:r.status,body:text?JSON.parse(text):null,cookie:r.headers.getSetCookie().map(x=>x.split(';')[0]).join('; ')};};
const signup=await call(ref.auth,'/sign-up/email',{name:'Owned',firstName:'Owned',lastName:'User',email:'org-policy@example.test',password:'owned-password'});assert.equal(signup.status,200);
const saved=structuredClone(ref.database),uid=signup.body.user.id,cookie=signup.cookie;
const secret=(await ref.auth.$context).secret;
const rows=[];
function setup(policy={},members=0){for(const key of Object.keys(ref.database))ref.database[key]=structuredClone(saved[key]);ref.database.user[0].emailVerified=true;
ref.database.user.push({...structuredClone(ref.database.user[0]),id:'target-user',email:'target-policy@example.test'});
ref.database.organization.push({id:'org-policy-existing',name:'Existing',slug:'existing',createdAt:new Date(),subscription:'free',status:'active'});
for(let i=0;i<members;i++)ref.database.member.push({id:'member-'+i,organizationId:'org-policy-existing',userId:i?('other-'+i):uid,role:i?'member':'viewer',createdAt:new Date()});
const auth=betterAuth({...ref.config,secret,logger:{disabled:true},rateLimit:{enabled:false},plugins:ref.config.plugins.map(p=>p.id==='organization'?organization({...p.options,...policy}):p)});return auth;}


for(const [role,expected]of [['viewer',400],['owner',200]]){const auth=setup({creatorRole:'viewer'},1);ref.database.member[0].role=role;const out=await call(auth,'/organization/leave',{organizationId:'org-policy-existing'},cookie);assert.equal(out.status,expected,JSON.stringify(out));rows.push({operation:'leave',role,status:out.status,code:out.body?.code});}
for(const [actor,target,second,expected]of [['viewer','owner',false,400],['owner','viewer',false,403],['viewer','owner',true,200]]){const auth=setup({creatorRole:'viewer'},1);ref.database.member[0].role=actor;if(second)ref.database.member.push({id:'second-viewer',organizationId:'org-policy-existing',userId:'target-user',role:'viewer',createdAt:new Date()});const out=await call(auth,'/organization/update-member-role',{organizationId:'org-policy-existing',memberId:'member-0',role:target},cookie);assert.equal(out.status,expected,JSON.stringify(out));rows.push({operation:'role',actor,target,second,status:out.status,code:out.body?.code});}
for(const [actor,expected]of [['owner',403],['viewer',200]]){const auth=setup({creatorRole:'viewer'},1);ref.database.member[0].role=actor;ref.database.organizationRole.push({id:'invite-grant',organizationId:'org-policy-existing',role:actor,permission:JSON.stringify({invitation:['create']}),createdAt:new Date()});const out=await call(auth,'/organization/invite-member',{organizationId:'org-policy-existing',email:'creator-invite@example.test',role:'viewer'},cookie);assert.equal(out.status,expected,JSON.stringify(out));rows.push({operation:'invite',actor,status:out.status,code:out.body?.code});}
for(const [actor,expected]of [['owner',400],['viewer',200]]){const auth=setup({creatorRole:'viewer'},1);ref.database.member[0].role=actor;ref.database.member.push({id:'target-creator',organizationId:'org-policy-existing',userId:'target-user',role:'viewer',createdAt:new Date()});ref.database.organizationRole.push({id:'delete-grant',organizationId:'org-policy-existing',role:actor,permission:JSON.stringify({member:['delete']}),createdAt:new Date()});const out=await call(auth,'/organization/remove-member',{organizationId:'org-policy-existing',memberIdOrEmail:'target-creator'},cookie);assert.equal(out.status,expected,JSON.stringify(out));rows.push({operation:'remove',actor,status:out.status,code:out.body?.code});}
for(const role of ['', ' viewer ', 'owner,viewer']){const auth=setup({creatorRole:role},0);const created=await call(auth,'/organization/create',{name:'ExactRole',slug:'exact-role'},cookie);assert.equal(created.status,200);assert.equal(created.body.members[0].role,role||'owner');const out=await call(auth,'/organization/leave',{organizationId:created.body.id},cookie);assert.equal(out.status,role.includes(',')?200:400);rows.push({operation:'exact-role-leave',role,status:out.status,code:out.body?.code});}
for(const count of [100,101]){const auth=setup({creatorRole:'viewer'},1);for(let i=1;i<count;i++)ref.database.member.push({id:'window-'+i,organizationId:'org-policy-existing',userId:'window-user-'+i,role:i===count-1?'viewer':'member',createdAt:new Date()});const out=await call(auth,'/organization/leave',{organizationId:'org-policy-existing'},cookie);assert.equal(out.status,count===100?200:400,JSON.stringify(out));rows.push({operation:'count-window',count,status:out.status,code:out.body?.code});}
console.log('PASS creator lifecycle audit'+rows.length,JSON.stringify(rows));
